# f12 【試作】大決戦MAX - キャンペーン M19 の最大構成を体感するための試作。
#
# 60x44・**自軍72 対 敵144**。M19 ではマップ本来の自軍24＋持ち越し48＝72に
# なるので、その「出撃させた数の倍」を敵に置いた状態を再現している。
# 合計216部隊。CPUの手番がどれくらい待たされるかを見るためのマップ。
# 待てないと感じたら、敵を最初から倍で置かずに増援で徐々に増やす案へ切り替える。
#
# 地形は決戦らしい広い正面。中央が陸で、周りをぐるりと海が囲む（艦隊の回り込み可）。
# 中央を縦に走る川は3か所だけ渡れる。両軍に飛行場あり。
# **地形は180度回転対称だが、部隊数は非対称**（敵が倍）。
#
# オプションの「CPUの手番の速さ」を最速にすると、思考時間だけが残る。
# 標準のままだと1部隊14フレームの演出待ちが144部隊ぶん乗るので、
# まず最速で試してから標準に戻して比べるとよい。
[map]
name             = 【試作】大決戦MAX
width            = 60
height           = 44
turns            = 80
timeout_winner   = -1
funds0           = 8000
funds1           = 12000

